    <!-- =========================================
         JAVASCRIPT: Slide Controller
         ========================================= -->
    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.totalSlides = this.slides.length;
                this.init();
            }

            init() {
                this.setupIntersectionObserver();
                this.setupProgressBar();
                this.setupNavDots();
                this.setupKeyboardNav();
                this.setupScrollNav();
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const slideNum = entry.target.dataset.slide;
                            this.currentSlide = parseInt(slideNum) - 1;
                            this.updateProgress();
                            this.updateNavDots();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupProgressBar() {
                this.progressBar = document.getElementById('progressBar');
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = progress + '%';
            }

            setupNavDots() {
                const navContainer = document.getElementById('navDots');
                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (index === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(index));
                    navContainer.appendChild(dot);
                });
                this.navDots = navContainer.querySelectorAll('.nav-dot');
            }

            updateNavDots() {
                this.navDots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === this.currentSlide);
                });
            }

            goToSlide(index) {
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        if (this.currentSlide < this.totalSlides - 1) {
                            this.goToSlide(this.currentSlide + 1);
                        }
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        if (this.currentSlide > 0) {
                            this.goToSlide(this.currentSlide - 1);
                        }
                    } else if (e.key === 'Home') {
                        e.preventDefault();
                        this.goToSlide(0);
                    } else if (e.key === 'End') {
                        e.preventDefault();
                        this.goToSlide(this.totalSlides - 1);
                    }
                });
            }

            setupScrollNav() {
                let isScrolling = false;
                window.addEventListener('wheel', (e) => {
                    if (isScrolling) return;
                    isScrolling = true;
                    setTimeout(() => isScrolling = false, 800);
                }, { passive: true });
            }
        }

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
